"""Dialogue engine importer. Reads output/graph.json as-is."""
import json

EDGE_KEYS = {"from", "to", "text"}


def load(path="output/graph.json"):
    with open(path) as f:
        data = json.load(f)
    nodes = {n["id"]: n for n in data["nodes"]}
    edges = []
    for e in data["edges"]:
        if set(e) != EDGE_KEYS:
            raise ValueError(f"unexpected edge keys: {sorted(e)}")
        edges.append((e["from"], e["to"], e["text"]))
    return nodes, edges

